function run(input, params, h) {
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const lines = [];
  for (let i = 1; i <= 11; i++) {
    h.tick();
    const word = low(params["w" + i]), says = String(params["s" + i] == null ? "" : params["s" + i]).trim();
    if (word && word !== "-" && says && says !== "-") lines.push({ word: word, says: says });
  }
  const own = w => lines.find(l => l.word === w);
  const pairs = text => String(text == null ? "" : text).split(",").map(p => p.split("=").map(low)).filter(p => p.length === 2 && p[0] && p[1]);
  const same = pairs(params.same1).concat(pairs(params.same2));
  const opposite = pairs(params.opp1).concat(pairs(params.opp2));
  const bringer = low(params.bw), brought = low(params.bt);
  const suggestions = [], knew = {}, unknown = {}, said = [];
  for (const c of (input.data || {}).choose || []) {
    h.tick();
    const words = (c.words || []).map(low);
    const all = words.concat(bringer !== "-" && words.indexOf(bringer) >= 0 && words.indexOf(brought) < 0 ? [brought] : []);
    const told = [];
    knew[c.name] = [];
    unknown[c.name] = [];
    for (const w of all) {
      h.tick();
      const from = words.indexOf(w) < 0 ? bringer : "";
      let known = w === bringer && own(brought) !== undefined;
      const mine = own(w);
      if (mine) {
        suggestions.push({ who: c.name, word: w, kind: "own", from: from, says: mine.says });
        told.push(w + (from ? " (" + from + " brings it)" : "") + " → " + mine.says);
        known = true;
      }
      for (const p of same) {
        h.tick();
        if (p[0] !== w || !own(p[1])) continue;
        suggestions.push({ who: c.name, word: w, kind: "same", like: p[1], says: own(p[1]).says });
        told.push(w + ", like " + p[1] + " → " + own(p[1]).says);
        known = true;
      }
      for (const p of opposite) {
        h.tick();
        if (p[0] !== w || !own(p[1])) continue;
        suggestions.push({ who: c.name, word: w, kind: "opposite", like: p[1], turn: true, says: own(p[1]).says });
        told.push(w + ", the opposite of " + p[1] + " → the opposite of “" + own(p[1]).says + "” (weaker)");
        known = true;
      }
      if (!from) (known ? knew : unknown)[c.name].push(w);
    }
    said.push("- **" + (((input.data || {}).called || {})[c.name] || c.name) + "**: " + (told.length ? told.join(" · ") : "nothing"));
  }
  let say = said.length ? said.join("\n") : "Nobody's words changed, so I have nothing new to suggest.";
  if (say.length > 1900) say = said.map(t => t.split(" → ")[0]).join("\n").slice(0, 1900);
  return { count: suggestions.length, suggestions: suggestions, knew: knew, unknown: unknown, say: say };
}

