function run(input, params, h) {
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const d = input.data || {};
  const call = n => (d.called || {})[n] || n;
  const lines = [];
  for (let i = 1; i <= 3; i++) {
    h.tick();
    const word = low(params["r" + i]), says = String(params["c" + i] == null ? "" : params["c" + i]).trim();
    if (word && word !== "-" && says && says !== "-") lines.push({ word: word, says: says });
  }
  const own = w => lines.find(l => l.word === w);
  const pairs = text => String(text == null ? "" : text).split(",").map(p => p.split("=").map(low)).filter(p => p.length === 2 && own(p[1]));
  const same = pairs(params.same), opposite = pairs(params.opposite);
  const choose = d.choose || [];
  const suggestions = [], unknown = {}, said = [];
  for (const r of d.relations || []) {
    h.tick();
    const mine = choose.filter(c => (c.of || c.name) === r.who || (c.of || c.name) === r.whom);
    if (!mine.length) continue;
    const verb = low(r.verb);
    const ways = (own(verb) ? [{ like: verb, turn: false }] : [])
      .concat(same.filter(p => p[0] === verb).map(p => ({ like: p[1], turn: false })))
      .concat(opposite.filter(p => p[0] === verb).map(p => ({ like: p[1], turn: true })));
    if (!ways.length) {
      unknown[r.who] = (unknown[r.who] || []).concat([verb]);
      continue;
    }
    for (const c of mine) {
      h.tick();
      const first = (c.of || c.name) === r.who;
      for (const way of ways) {
        h.tick();
        suggestions.push({ who: c.name, of: first ? r.whom : r.who, word: verb, kind: "comparison", like: way.like, turn: first ? way.turn : !way.turn, says: own(way.like).says });
      }
    }
    said.push("- " + call(r.who) + " " + verb + " " + call(r.whom) + (ways[0].like !== verb ? " (" + (ways[0].turn ? "the opposite of " : "like ") + ways[0].like + ")" : "") + " → " + call(r.who) + ", compared with " + call(r.whom) + ": " + (ways[0].turn ? "the opposite of “" + own(ways[0].like).says + "”" : own(ways[0].like).says) + "; " + call(r.whom) + ": the other way round");
  }
  const say = (said.length ? said.join("\n") : "There are no comparisons to make for anyone being chosen.");
  return { count: suggestions.length, suggestions: suggestions, unknown: unknown, say: say };
}

