      if (used.indexOf(low(phrase) + " (" + r.by + ")") < 0) used.push(low(phrase) + " (" + r.by + ")");
      const kind = p.dir !== undefined ? "comparison" : x.kind;
      const turn = !!x.turn;
      const v = p.v === undefined ? undefined : turn ? 4 - p.v : p.v, dir = p.dir === undefined ? undefined : turn ? -p.dir : p.dir;
