        if (!beingChosen.has(who)) continue;
        if (!sugs.has(who)) sugs.set(who, []);
        sugs.get(who).push({ n: n++, v: v, dir: dir, of: x.of, not: p.not, w: p.s * (weights[kind] || 0), src: p.not ? "“" + NOT + " " + valueWord(v) + "” (" + said + ")" : said });
        if (kind !== "taste" && kind !== "comparison" && from.indexOf(r.by) < 0) from.push(r.by);
      }
