      const film = w.because.filter(x => x.indexOf(FILM) === 0).map(x => x.slice(FILM.length)), own = w.because.filter(x => x.indexOf(FILM) !== 0);
      list.push(w.value + " because of " + joinAnd(own.concat(film.length ? [FILM + joinAnd(film)] : [])) + (w.against.length ? ", against " + joinAnd(w.against) : "") + (w.how === STRONG ? "" : " (" + w.how + ")"));
    }
    explain[name] = cap(call(name)) + (list.length ? " is " + list.join("; ") + "." : "") + (mid.length ? " " + cap(levels[1]) + ": " + joinAnd(mid) + "." : "");
  }
  const target = chosenNow.find(nm => low(nm) === low(params.explain)) || chosenNow[0];
  let say = "**Scene " + scene.scene + " of " + scene.of + ".** " + (target ? "**Why " + call(target) + " is like that:** " + explain[target] + "\n\n" : "");
  say += (chosenNow.length ? "The " + things.length + " choosers chose for " + joinAnd(chosenNow.map(call)) + "; I only put their answers together:\n" : "Nobody's words changed, so everyone keeps the values chosen before:\n") +
    Object.keys(summary).map(nm => "- **" + call(nm) + "**: " + summary[nm]).join("\n");
  const parts = [[tally.more, STRONG], [tally.middle, "met in the middle"], [tally.stronger, "stronger"], [tally.first, "said first"], [tally.alone, "unopposed"], [tally.nobody, "nothing suggested"], [tally.self, "kept a comparison's own direction"]].filter(x => x[0] > 0);
  if (chosenNow.length) say += "\n\n**Settled, by the choosers:** " + parts.map(x => x[0] + " " + x[1]).join(", ") + ". " + tally.waited + (tally.waited === 1 ? " comparison" : " comparisons") + " waited for another's value" + (tally.without ? "; " + tally.without + " went without, because two choices waited for each other (Ani's “deadly embrace”)" : "") + ".";
