code.js:
function run(input, params, h) {
  const WAYS = ["keeps away", "chases off", "looms over", "stands guard", "goes along", "come together", "goes to and changes", "comes closer bit by bit"];
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const listOf = s => String(s == null ? "" : s).split(",").map(low).filter(w => w && w !== "-");
  const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
  const d = input.data || {};
  const memory = input.memory || { used: [] };
  const choices = d.choices || {}, onStage = d.onStage || [];
  const call = n => (d.called || {})[n] || n;
  const value = (who, el) => (choices[who] || {})[el] || 2;
  const friends = (a, b) => (d.friends || []).some(p => (p[0] === a && p[1] === b) || (p[0] === b && p[1] === a));
  const standIn = who => ((d.standIns || []).find(s => s.of === who) || {}).name || "";
  const verbWays = [[low(params.dominates), listOf(params.dominatesWays)], [low(params.keeps), listOf(params.keepsWays)], [low(params.helps), listOf(params.helpsWays)], [low(params.meets), listOf(params.meetsWays)], [low(params.other), listOf(params.otherWays)]].filter(x => x[0] && x[0] !== "-");
  const plan = [], notes = [], unknown = [];
  const says = s => {
    const a = call(s.who), b = call(s.whom || ""), c = call(s.third || "");
    return cap(s.way === "keeps away" ? a + " keeps away from " + b : s.way === "chases off" ? a + " chases " + b + " off" : s.way === "looms over" ? a + " looms over " + b
      : s.way === "stands guard" ? a + " stands guard between " + b + " and " + c : s.way === "goes along" ? a + " goes along with " + b : s.way === "come together" ? a + " and " + b + " come together"
      : s.way === "goes to and changes" ? a + " goes to " + b + " and changes " + b : s.way === "comes closer bit by bit" ? a + " comes closer, bit by bit" : a + " moves about in its own way");
  };
  const crossedOut = (way, task) => {
    const needs = way === "stands guard" ? [task.whom, task.third] : way === "comes closer bit by bit" ? [] : [task.whom];
    const away = needs.find(n => !n || onStage.indexOf(n) < 0);
    if (away !== undefined) return way + " needs " + (away ? call(away) + " on stage" : "someone else on stage who isn't a friend");
    if ((way === "chases off" || way === "stands guard") && !(value(task.who, "speed") > value(task.whom, "speed"))) return way + ": " + call(task.who) + " isn't faster than " + call(task.whom);
    if (way === "keeps away" && value(task.who, "strangers") === 3) return way + ": " + call(task.who) + " is drawn to strangers";
    return "";
  };
  const bestWhen = (way, task) => {
    if (way === "chases off" && value(task.who, "size") > value(task.whom, "size")) return "best when " + call(task.who) + " is bigger than " + call(task.whom);
    if (way === "stands guard" && (d.relations || []).some(r => r.who === task.who && r.whom === task.whom && low(r.verb) === low(params.dominates))) return "best when " + call(task.who) + " dominates " + call(task.whom);
    if ((way === "goes along" || way === "come together") && value(task.who, "friends") === 3) return "best when " + call(task.who) + " is drawn to friends";
    return "";
  };
  const pick = (task, ways) => {
    const ok = [];
    for (const way of ways) {
      h.tick();
      if (WAYS.indexOf(way) < 0) {
        if (unknown.indexOf(way) < 0) unknown.push(way);
        continue;
      }
      const no = crossedOut(way, task);
      if (no) {
        notes.push("crossed out " + no);
        continue;
      }
      ok.push({ way: way, best: bestWhen(way, task), fresh: memory.used.indexOf(way) < 0 });
    }
    ok.sort((x, y) => (y.best ? 2 : 0) + (y.fresh ? 1 : 0) - (x.best ? 2 : 0) - (x.fresh ? 1 : 0));
    if (!ok.length) return { way: "moves about", who: task.who, because: task.because + (ways.length ? "; no way was left" : "") };
    for (const other of ok.slice(1)) {
      h.tick();
      notes.push(other.way + " was passed over for " + ok[0].way + (ok[0].best ? " (" + ok[0].best + ")" : ok[0].fresh && !other.fresh ? " (the film hasn't used it yet)" : ""));
    }
    return { way: ok[0].way, who: task.who, whom: task.whom || "", third: task.third || "", because: task.because + (ok[0].best ? "; " + ok[0].best : "") };
  };
  const shy = listOf(params.shyWords), mean = listOf(params.meanWords);
  for (const e of d.events || []) {
    h.tick();
    const verb = low(e.verb);
    if (verb === low(params.becomes) && (e.what || []).length) {
      const feeling = low(e.what[0]), words = feeling === low(params.happy) ? listOf(params.happyWays) : feeling === low(params.sad) ? listOf(params.sadWays) : [];
      const changes = {};
      for (const w of words) {
        h.tick();
        const el = Object.keys(d.words || {}).find(id => d.words[id][3] === w || d.words[id][2] === w);
        if (el) changes[el] = d.words[el][3] === w ? 1 : -1;
        else if (unknown.indexOf(w) < 0) unknown.push(w);
      }
      plan.push({ way: "feels", who: e.who, feeling: feeling, changes: changes, because: "", says: cap(call(e.who)) + " becomes " + feeling + ": " + words.join(", ") });
      continue;
    }
    if (verb === low(params.changes)) {
      if (!listOf(e.whom ? params.changesWays : params.selfWays).length && unknown.indexOf(e.verb) < 0) unknown.push(e.verb);
      const step = e.whom ? pick({ who: e.who, whom: e.whom, because: (e.from || []).join(" ") + " → " + (e.to || []).join(" ") }, listOf(params.changesWays)) : pick({ who: e.who, because: (e.from || []).join(" ") + " → " + (e.to || []).join(" ") }, listOf(params.selfWays));
      step.standIn = standIn(e.whom || e.who);
      plan.push(step);
      continue;
    }
    const others = onStage.filter(n => n !== e.who && !friends(n, e.who));
    let ways = [], task = { who: e.who, whom: e.whom, third: e.also, because: e.verb };
    if ((e.what || []).length) {
      const word = e.what.find(w => shy.indexOf(low(w)) >= 0 || mean.indexOf(low(w)) >= 0);
      ways = !word ? [] : shy.indexOf(low(word)) >= 0 ? listOf(params.shyWays) : listOf(params.meanWays);
      if (word && !ways.length && unknown.indexOf(word) < 0) unknown.push(word);
      task = { who: e.who, whom: others[0] || "", because: word || e.what.join(", ") };
    } else {
      const vw = verbWays.find(x => x[0] === verb);
      if (vw && vw[1].length) ways = vw[1];
      else if (unknown.indexOf(verb) < 0) unknown.push(verb);
    }
    plan.push(pick(task, ways));
  }
  for (const s of plan) {
    h.tick();
    if (!s.says) s.says = says(s);
    if (memory.used.indexOf(s.way) < 0 && s.way !== "moves about" && s.way !== "feels") memory.used.push(s.way);
  }
  const shown = {}, strengths = {};
  for (const name of onStage.concat((d.standIns || []).map(s => s.name))) {
    h.tick();
    if (choices[name]) shown[name] = choices[name];
    if ((d.strengths || {})[name]) strengths[name] = d.strengths[name];
  }
  const say = "**Scene " + d.scene + "'s plan:**\n" + plan.map((s, i) => (i + 1) + ". " + s.says + (s.because ? " (" + s.because + ")" : "") + ".").join("\n") +
    (notes.length ? "\n\n" + cap(notes.join("; ")) + "." : "") + (unknown.length ? "\n\nNobody has taught me a way to show these yet: " + unknown.join(", ") + "." : "");
  return { scene: d.scene, of: d.of, title: d.title, cast: d.cast, called: d.called, onStage: onStage, plan: plan, ways: plan.map(s => s.way), choices: shown, strengths: strengths, standIns: d.standIns || [],
    summary: d.summary, looksFrom: d.looksFrom || [], tasteLevel: d.tasteLevel || {}, changeFrames: +params.changeFrames || 0, notes: notes, untaught: unknown, say: say, memory: memory };
}

function run(input, params, h) {
  const d = input.data || {};
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const listOf = s => String(s == null ? "" : s).split(",").map(low);
  const three = (v, x) => (Array.isArray(v) && v.length === 3 ? v.map(Number) : x);
  const r1 = v => Math.round(v * 10) / 10;
  const call = n => (d.called || {})[n] || n;
  const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
  const SHAPES = { circle: [16, 22.5], square: [4, 90], pentagon: [5, 72], triangle: [3, 120], star: [5, 144], "nine-point star": [9, 160], flower: [6, 60] };
  const HUES = { red: [255, 70, 60], orange: [255, 150, 40], yellow: [250, 220, 50], green: [70, 210, 80], blue: [100, 160, 255], purple: [180, 100, 240], pink: [255, 130, 200], white: [240, 240, 240], gray: [160, 160, 160], brown: [190, 120, 60] };
  const table = [listOf(params.smooth), listOf(params.middle), listOf(params.pointed)];
  const outlines = three(params.outlines, [1, 2, 3]), sizes = three(params.sizes, [14, 22, 32]), lights = three(params.lights, [55, 80, 100]);
  const hues = [listOf(params.cool), listOf(params.mild), listOf(params.warm)], kens = listOf(params.kens), kensColors = listOf(params.kensColors);
  const speeds = three(params.speeds, [5, 10, 16]), waves = three(params.waves, [0, 10, 22]), jolts = three(params.jolts, [0, 3, 8]);
  const spins = three(params.spins, [3, 12, 30]), heights = three(params.heights, [-50, 0, 50]), turns = three(params.turns, [3, 2, 1]);
  const choices = d.choices || {}, strengths = d.strengths || {}, ken = (d.looksFrom || []).length === 0;
  const screen = low(params.screen) === "black";
  const color = (hue, light) => "[" + (HUES[hue] || HUES.gray).map(c => Math.round(c * light / 100)).join(" ") + "]";
  const nameOf = (shape, detail) => (table[shape - 1] || [])[detail - 1] || "-";
  const notes = [], figures = [], current = {}, pos = {};
  const memory = input.memory || {};
  memory.colors = memory.colors || {};
  const hueFor = (of, list) => {
    if (list.indexOf(memory.colors[of]) >= 0) return memory.colors[of];
    const taken = Object.keys(memory.colors).filter(n => n !== of).map(n => memory.colors[n]);
    const hue = list.find(c => taken.indexOf(c) < 0) || list.slice().sort((a, b) => taken.filter(c => c === a).length - taken.filter(c => c === b).length)[0] || "gray";
    memory.colors[of] = hue;
    return hue;
  };
  const level = (v, el, by) => Math.max(1, Math.min(3, (v[el] || 2) + (by || 0))) - 1;
  const figure = (name, of) => {
    const v = choices[name] || {};
    const f = { name: name, of: of, id: figures.length + 1, v: v, proc: "C_" + Array.from(name.toUpperCase()).map(c => (c.toLowerCase() !== c.toUpperCase() || (c >= "0" && c <= "9") ? c : "_")).join("") };
    let shape = v.shape || 2, detail = v.detail || 2, kind = nameOf(shape, detail);
    if (ken) {
      const i = Math.max(0, (d.cast || []).indexOf(of)) % Math.max(1, kens.length);
      f.kind = SHAPES[kens[i]] ? kens[i] : "star";
      f.outlines = outlines[0];
      f.r = sizes[1];
      f.hue = kensColors[i % Math.max(1, kensColors.length)];
      f.light = 100;
      f.looks = f.hue + " " + f.kind;
    } else {
      if (!SHAPES[kind]) {
        const s = strengths[name] || {};
        const margin = (nets, val) => (nets ? nets[val - 1] - nets.filter((x, j) => j !== val - 1).reduce((a, b) => Math.max(a, b), -1e9) : 0);
        const order = (nets, val) => [1, 2, 3].filter(x => x !== val).sort((a, b) => (nets ? nets[b - 1] - nets[a - 1] : 0));
        const tries = margin(s.detail, detail) <= margin(s.shape, shape) ? [["detail", order(s.detail, detail)], ["shape", order(s.shape, shape)]] : [["shape", order(s.shape, shape)], ["detail", order(s.detail, detail)]];
        for (const t of tries) {
          h.tick();
          const again = t[1].find(x => SHAPES[t[0] === "detail" ? nameOf(shape, x) : nameOf(x, detail)]);
          if (again === undefined || SHAPES[kind]) continue;
          if (t[0] === "detail") detail = again;
          else shape = again;
          kind = nameOf(shape, detail);
          notes.push(cap(call(of)) + (of !== name ? " after the change" : "") + " is " + ["smooth", "medium", "pointed"][(v.shape || 2) - 1] + " with " + ["simple", "medium", "fancy"][(v.detail || 2) - 1] + " detail, and no shape is both, so the weaker choice, " + t[0] + ", was made again: " + kind + ".");
        }
      }
      f.kind = SHAPES[kind] ? kind : "circle";
      f.outlines = outlines[detail - 1];
      f.r = sizes[level(v, "size")];
      f.hue = hueFor(of, hues[level(v, "warmth")]);
      f.light = lights[level(v, "brightness")];
      f.looks = ["small", "medium-sized", "big"][level(v, "size")] + " " + ["dim ", "", "bright "][level(v, "brightness")] + f.hue + " " + f.kind;
    }
    f.speed = speeds[level(v, "speed")];
    f.wave = waves[level(v, "curves")];
    f.jolt = jolts[level(v, "jerkiness")];
    f.spin = spins[level(v, "liveliness")];
    f.turns = turns[level(v, "purpose")];
    f.color = color(f.hue, f.light);
    figures.push(f);
    return f;
  };
  const onStage = (d.onStage || []).filter(n => choices[n]);
  onStage.forEach((n, i) => {
    const f = figure(n, n);
    current[n] = f;
    pos[f.id] = { x: onStage.length === 1 ? 0 : -160 + 320 * i / (onStage.length - 1), y: heights[level(f.v, "height")] };
  });
  const afterOf = {};
  for (const s of d.standIns || []) {
    h.tick();
    if (choices[s.name] && current[s.of]) afterOf[s.of] = figure(s.name, s.of);
  }
  const segs = [];
  const side = (a, b) => (pos[a.id].x <= pos[b.id].x ? 1 : -1);
  const clampX = x => Math.max(-225, Math.min(225, x));
  const frames = (dist, speed) => Math.max(3, Math.min(24, Math.round(dist / Math.max(1, speed))));
  const line = (f, x1, y1) => ({ x0: pos[f.id].x, y0: pos[f.id].y, x1: clampX(x1), y1: y1 });
  const dist = (f, x1, y1) => Math.sqrt((pos[f.id].x - x1) * (pos[f.id].x - x1) + (pos[f.id].y - y1) * (pos[f.id].y - y1));
  const seg = (step, n, moves, extra) => {
    const from = {};
    for (const f of figures) {
      h.tick();
      if (pos[f.id]) from[f.id] = { x0: pos[f.id].x, y0: pos[f.id].y, x1: pos[f.id].x, y1: pos[f.id].y };
    }
    for (const id of Object.keys(moves)) {
      h.tick();
      const mv = moves[id];
      if (mv.x1 === undefined) continue;
      from[id] = mv;
      pos[id] = { x: mv.x1, y: mv.y1 };
    }
    const s = { step: step, n: n, moves: moves, from: from, makes: "", before: [], after: [] };
    for (const k of Object.keys(extra || {})) {
      h.tick();
      s[k] = extra[k];
    }
    segs.push(s);
    return s;
  };
  const lowLevel = (d.tasteLevel || {}).complexity === 1;
  (d.plan || []).forEach((p, i) => {
    const a = current[p.who], b = current[p.whom], c = current[p.third], m = {}, m2 = {};
    if (!a) return;
    if (p.way === "feels") {
      const ch = p.changes || {}, v = {};
      for (const el of Object.keys(a.v)) {
        h.tick();
        v[el] = a.v[el];
      }
      for (const el of Object.keys(ch)) {
        h.tick();
        v[el] = level(v, el, ch[el]) + 1;
      }
      a.v = v;
      a.speed = speeds[level(v, "speed")];
      const makes = "MAKE \"S" + a.id + " " + spins[level(v, "liveliness")] + " MAKE \"W" + a.id + " " + waves[level(v, "curves")] + " MAKE \"J" + a.id + " " + jolts[level(v, "jerkiness")] + (ken || !ch.brightness ? "" : " MAKE \"C" + a.id + " " + color(a.hue, lights[level(v, "brightness")]));
      if (!lowLevel && segs.length) {
        const first = segs.find(s => s.step === segs[segs.length - 1].step);
        first.makes += (first.makes ? " " : "") + makes;
        first.also = (first.also || []).concat([i]);
        return;
      }
      m[a.id] = { orbit: true };
      seg(i, frames(110, a.speed), m, { makes: makes });
      return;
    }
    if (p.way === "keeps away" && b) {
      m[a.id] = line(a, pos[a.id].x - side(a, b) * 100, pos[a.id].y + 15);
