      m[a.id] = line(a, m[b.id].x1 - s * 45, pos[b.id].y);
      seg(i, n1, m);
      m2[a.id] = line(a, s * 190, pos[b.id].y);
      m2[b.id] = line(b, s * 235, pos[b.id].y);
      seg(i, frames(Math.abs(s * 190 - pos[a.id].x), a.speed), m2);
    } else if (p.way === "looms over" && b) {
      m[a.id] = line(a, pos[b.id].x, pos[b.id].y + 70);
      seg(i, frames(dist(a, pos[b.id].x, pos[b.id].y + 70), a.speed), m);
