    } else if (p.way === "come together" && b) {
      const s = side(a, b), mx = (pos[a.id].x + pos[b.id].x) / 2, my = (pos[a.id].y + pos[b.id].y) / 2;
      const n = Math.max(frames(dist(a, mx, my), a.speed), frames(dist(b, mx, my), b.speed));
