      }
    } else if (p.way === "comes closer bit by bit") {
      const g = afterOf[p.who];
      const near = onStage.map(n => current[n]).filter(f => f && f.of !== a.of).sort((x, y) => Math.abs(pos[x.id].x - pos[a.id].x) - Math.abs(pos[y.id].x - pos[a.id].x))[0];
      const tx = near ? (pos[a.id].x + pos[near.id].x) / 2 : pos[a.id].x, ty = near ? (pos[a.id].y + pos[near.id].y) / 2 : pos[a.id].y;
