    left.push("the comments");
  }
  if (logo.length > 3900) {
    logo = write(false, false, keep);
    left.push("the names");
  }
  while (logo.length > 3900 && keep > 1) {
    h.tick();
    keep--;
    logo = write(false, false, keep);
