  say += ken ? "\n\nNo expert said anything about looks, so they look as Ken drew them in 1978, in the Cast's order: " + figures.filter(f => f.name === f.of).map(f => call(f.name) + " a " + f.looks).join(", ") + "."
    : "\n\n**How they look:** " + figures.map(f => call(f.name) + ": " + f.looks + (f.outlines > 1 ? " (" + f.outlines + " outlines)" : "")).join("; ") + ".";
  if (notes.length) say += "\n\n" + notes.join(" ");
