  if (left.length) say += "\n\nThe program was too long, so I left out " + left.join(", ") + ".";
  return { program: logo, fits: logo.length <= 3900, frames: at, seconds: r1(at / perSecond), steps: steps.map(s => ({ from: s.from, to: s.to, what: s.what })), looks: looks, say: say, memory: memory };
}
